INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Anpassung eines Systems durch Parameter immer codefrei?', 2, '[{"text": "Nein", "correct": true, "because": "Manche Parameter erfordern Codeänderungen"}, {"text": "Ja", "correct": false, "because": "Nicht immer ohne Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel, wenn ich ein System durch Parameter anpasse?', 3, '[{"text": "Flexibilität", "correct": true, "because": "Ermöglicht einfache Anpassungen"}, {"text": "Maximale Komplexität", "correct": false, "because": "Gegenteil des Ziels"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Automatisierung bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale machen eine solche Anpassung nützlich?', 5, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Code bleibt generisch"}, {"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Anforderungen an"}, {"text": "Hohe Latenz", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Feste Struktur", "correct": false, "because": "Einschränkt Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Parameter ermöglichen Konfigurationsänderungen. b) Sie ersetzen Programmierung komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ergänzt, ersetzt nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung einer solchen Anpassung?', 4, '[{"text": "Dokumentation", "correct": false, "because": "Klärt Parameterzweck"}, {"text": "Wertebereiche", "correct": false, "because": "Sichern Funktion"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Parameter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Parameter immer in Konfigurationsdateien stehen?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch via Kommandozeile gesetzt sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Dateien beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist entscheidend für effektive Parameter?', 3, '[{"text": "Klarheit", "correct": true, "because": "Vermeidet Missverständnisse"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von einer solchen Anpassung?', 5, '[{"text": "Datenbankkonfiguration", "correct": true, "because": "Erlaubt flexible Einstellungen"}, {"text": "Webserver", "correct": true, "because": "Passt sich Last an"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Spezialisierte Schnittstellen"}, {"text": "Bildbearbeitung", "correct": false, "because": "Andere Prioritäten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Parameter reduzieren Entwicklungsaufwand. b) Sie sind immer benutzerfreundlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Design ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine solche Anpassung?', 4, '[{"text": "Validierung", "correct": false, "because": "Sichert korrekte Werte"}, {"text": "Dokumentation", "correct": false, "because": "Hilft bei Nutzung"}, {"text": "3D-Modellierung", "correct": true, "because": "Kein Parameterbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Parameter nur für Software relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Hardwarekonfiguration"}, {"text": "Ja", "correct": false, "because": "Breiter Anwendungsbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei einer solchen Anpassung?', 4, '[{"text": "Falsche Werte", "correct": true, "because": "Können Fehler auslösen"}, {"text": "Komplexe Abhängigkeiten", "correct": true, "because": "Erschweren Konfiguration"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Parameterproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Parameter immer statisch sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Können dynamisch gesetzt werden"}, {"text": "Ja", "correct": false, "because": "Dynamische Optionen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Definition von Parametern?', 3, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Maximale Anzahl", "correct": false, "because": "Kann verwirren"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Parameter ermöglichen Wiederverwendung. b) Sie benötigen immer eine GUI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine solche Anpassung?', 5, '[{"text": "Einfache Anpassung", "correct": true, "because": "Keine Codeänderung nötig"}, {"text": "Konsistenz", "correct": true, "because": "Gleiche Logik, andere Werte"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher ein Nachteil"}, {"text": "Feste Werte", "correct": false, "because": "Gegenteil von Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer solchen Anpassung unwichtig?', 3, '[{"text": "Wertevalidierung", "correct": false, "because": "Sichert Funktion"}, {"text": "Standardwerte", "correct": false, "because": "Vereinfachen Nutzung"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Parameterfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern Parameter immer eine Datei?', 3, '[{"text": "Nein", "correct": true, "because": "Können auch via API gesetzt sein"}, {"text": "Ja", "correct": false, "because": "Nicht auf Dateien beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Parameter für Endnutzer geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "Mit guter Dokumentation"}, {"text": "Nein", "correct": false, "because": "Auch für Nutzer zugänglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einer solchen Anpassung?', 4, '[{"text": "Konfiguration eines Webservers", "correct": true, "because": "Ermöglicht flexible Einstellungen"}, {"text": "3D-Animation", "correct": false, "because": "Andere Prioritäten"}, {"text": "Netzwerkwartung", "correct": false, "because": "Physikalische Aufgabe"}]');
